'use strict';
// Synthetic design simulation only. No API, persistence, upload or authorization.
const params=new URLSearchParams(location.search);
const lang=['ru','az','en'].includes(params.get('lang'))?params.get('lang'):'ru';
const screen=document.body.dataset.screen;
let state=params.get('state')||'default';
let actor=params.get('actor')==='person'?'person':'organization'; let firstConsent=params.get('consent')==='person'?'person':'organization';
let consentHistory=['both','person','organization'].includes(params.get('consentHistory'))?params.get('consentHistory'):'none';
const languageUrl=l=>{const q=new URLSearchParams(params);q.set('lang',l);q.set('state',state);q.set('actor',actor);q.set('consent',firstConsent);q.set('consentHistory',consentHistory);return `${screen}.html?${q}`;};
const t=(ru,en,az)=>({ru,en,az}[lang]);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=n=>`<span class="icon" aria-hidden="true">${n}</span>`;
const names={index:t('Экраны специалистов','Specialist screens','Mütəxəssis ekranları'),profile:t('Публичный профиль','Public profile','İctimai profil'),person:t('Мой профиль','My profile','Mənim profilim'),organization:t('Специалисты организации','Organization specialists','Təşkilatın mütəxəssisləri'),claim:t('Подтверждение личности','Claim your profile','Profili təsdiqləmək'),documents:t('Мои документы','My documents','Mənim sənədlərim'),review:t('Проверка KidsMap','KidsMap review','KidsMap yoxlaması'),reconciliation:t('Сверка переноса','Transfer reconciliation','Köçürmənin tutuşdurulması')};
const icons={index:'grid_view',profile:'person',person:'edit',organization:'groups',claim:'verified_user',documents:'folder',review:'fact_check',reconciliation:'compare_arrows'};
const url=(page,st='default',extra='')=>`${page}.html?lang=${lang}&state=${st}${extra}`;
const pill=(text,kind='')=>`<span class="pill ${kind}">${text}</span>`;
const button=(label,action,kind='secondary',extra='')=>`<button type="button" class="btn ${kind}" data-action="${action}" ${extra}>${label}</button>`;
const notice=(title,body,kind='')=>`<div class="notice ${kind}"><strong>${title}</strong><p>${body}</p></div>`;
const head=(title,desc)=>`<div class="page-head"><div><p class="eyebrow">${t('Специалисты · KidsMap','Specialists · KidsMap','Mütəxəssislər · KidsMap')}</p><h1>${title}</h1><p class="lede">${desc}</p></div></div>`;
const field=(id,label,value='',type='text',help='',required=false)=>`<div class="field"><label for="${id}">${label}${required?' *':''}</label><input id="${id}" name="${id}" type="${type}" value="${esc(value)}" ${required?'required':''} ${help?`aria-describedby="${id}-help"`:''}><p class="help" id="${id}-help">${help}</p></div>`;
const states=['default','empty','pending','active','history','error','conflict','denied','rejected','approved','withdrawn','saved','revoked','loading'];
if(!states.includes(state))state='default';
const stateNames={default:t('Основной экран','Default screen','Əsas ekran'),empty:t('Нет записей','No records','Qeyd yoxdur'),pending:t('Ожидает подтверждения','Awaiting confirmation','Təsdiq gözləyir'),active:t('Подтверждено обеими сторонами','Confirmed by both parties','Hər iki tərəf təsdiqləyib'),history:t('История участия','Participation history','İştirak tarixçəsi'),error:t('Ошибка формы','Form error','Forma xətası'),conflict:t('Версия изменилась','Version conflict','Versiya dəyişib'),denied:t('Доступ ограничен','Access restricted','Giriş məhduddur'),rejected:t('Отклонено','Rejected','Rədd edilib'),approved:t('Одобрено KidsMap','Approved by KidsMap','KidsMap təsdiqləyib'),withdrawn:t('Заявка отозвана','Claim withdrawn','Müraciət geri götürülüb'),saved:t('Сохранено в макете','Saved in prototype','Maketdə saxlanıldı'),revoked:t('Публичный выбор отменён','Public choice withdrawn','İctimai seçim ləğv edilib'),loading:t('Загрузка','Loading','Yüklənir')};
function commonState(){
 if(state==='conflict')return notice(t('Данные изменились','These details have changed','Məlumatlar dəyişib'),t('Откройте актуальную версию перед повторным действием. Чужие изменения не будут перезаписаны.','Load the latest version before trying again. Other changes will not be overwritten.','Yenidən cəhd etməzdən əvvəl son versiyanı açın. Digər dəyişikliklər üzərinə yazılmayacaq.'),'warn')+`<div class="actions">${button(t('Открыть актуальную версию','Load latest version','Son versiyanı aç'),'reload')}</div>`;
 if(state==='loading')return `<div class="notice" role="status" aria-busy="true">${t('Загружаем данные…','Loading details…','Məlumatlar yüklənir…')}</div>`;
 if(state==='error')return notice(t('Проверьте введённые данные','Check your details','Daxil edilən məlumatları yoxlayın'),t('Отмеченные поля требуют внимания. Изменения пока не сохранены.','The marked fields need attention. Your changes have not been saved.','İşarələnmiş sahələri yoxlayın. Dəyişikliklər hələ saxlanılmayıb.'),'bad');
 if(state==='saved')return notice(t('Изменения сохранены в макете','Changes saved in this prototype','Dəyişikliklər maketdə saxlanıldı'),t('Это демонстрационное состояние, без записи в KidsMap.','This is a demonstration state. Nothing was written to KidsMap.','Bu nümayiş vəziyyətidir. KidsMap-a heç nə yazılmayıb.'));
 return '';
}
function denied(){return head(t('Личные сведения защищены','Personal details are protected','Şəxsi məlumatlar qorunur'),t('Доступ к месту или организации не даёт доступа к личности специалиста.','Managing a place or organization does not grant access to a specialist’s identity.','Məkan və ya təşkilatı idarə etmək mütəxəssisin şəxsi profilinə giriş vermir.'))+notice(t('У вас нет доступа к этому экрану','You do not have access to this screen','Bu ekrana girişiniz yoxdur'),t('Биографию, личные контакты и выбор публичных документов меняет подтверждённый специалист. Приватные документы проверяет только назначенный проверяющий KidsMap.','Only the verified specialist edits their biography, personal contacts and public document choices. Private documents are reviewed only by a dedicated KidsMap reviewer.','Bioqrafiyanı, şəxsi əlaqələri və ictimai sənəd seçimini yalnız təsdiqlənmiş mütəxəssis dəyişir. Məxfi sənədləri yalnız xüsusi səlahiyyətli KidsMap yoxlayıcısı yoxlayır.'),'warn')+`<a class="btn secondary" href="${url('organization')}">${t('К связям организации','Organization cooperation','Təşkilat əlaqələrinə')}</a>`;}
function index(){return head(t('Специалист — человек, а не филиал','A specialist is a person, not a branch','Mütəxəssis filial deyil, insandır'),t('Профиль для родителей, личный кабинет и понятные границы сотрудничества с организациями.','A profile for parents, a personal workspace and clear boundaries for cooperation with organizations.','Valideynlər üçün profil, şəxsi kabinet və təşkilatlarla əməkdaşlığın aydın sərhədləri.'))+notice(t('Макеты specialist-25-r1 · на рассмотрении','specialist-25-r1 designs · awaiting acceptance','specialist-25-r1 maketləri · qəbul gözlənilir'),t('Все сведения вымышлены. Действия показывают состояния интерфейса; приложение и данные не изменяются.','All details are synthetic. Actions demonstrate interface states; the application and data remain unchanged.','Bütün məlumatlar uydurmadır. Əməliyyatlar interfeys vəziyyətlərini göstərir; tətbiq və məlumatlar dəyişmir.'))+`<div class="gallery">${Object.keys(names).filter(k=>k!=='index').map(k=>`<a class="screen-card" href="${url(k)}">${icon(icons[k])}<h2>${names[k]}</h2><p>${descriptions[k]}</p><span>${t('Посмотреть экран','Explore screen','Ekrana bax')} →</span></a>`).join('')}</div>`;}
const descriptions={profile:t('Возраст, специализации, практика, онлайн и публичные квалификации.','Ages, specialties, practice, online sessions and public qualifications.','Yaş, ixtisaslar, praktika, onlayn və ictimai kvalifikasiyalar.'),person:t('Личные сведения, независимый кабинет и история мест практики.','Personal details, independent practice and location history.','Şəxsi məlumatlar, müstəqil kabinet və praktika məkanlarının tarixçəsi.'),organization:t('Приглашение с ролью и периодом. Два отдельных согласия.','Invitation with a role and period. Two separate consents.','Vəzifə və müddətlə dəvət. İki ayrı razılıq.'),claim:t('Проверка KidsMap вместо автоматического владения профилем.','KidsMap verification instead of automatic profile ownership.','Avtomatik profil sahibliyi əvəzinə KidsMap yoxlaması.'),documents:t('Личность всегда приватна. Публикация квалификации — отдельный выбор.','Identity stays private. Sharing a qualification is a separate choice.','Şəxsiyyət həmişə məxfidir. Kvalifikasiyanın paylaşılması ayrı seçimdir.'),review:t('Раздельные решения о личности и документах; публичный выбор не reviewer scope.','Separate identity and document decisions; public choice belongs to the person.','Şəxsiyyət və sənədlər üzrə ayrı qərarlar; ictimai seçim şəxsin özünə aiddir.'),reconciliation:t('Сохранение ID и старого URL. Неоднозначные записи — на ручную проверку.','Preserve IDs and old URLs. Ambiguous records require manual review.','ID və köhnə URL saxlanılır. Qeyri-müəyyən qeydlər əl ilə yoxlanılır.')};
const personName=t('Лейла Мамедова','Leyla Mammadova','Leyla Məmmədova');
const roleName=t('Логопед','Speech therapist','Loqoped');
const bio=t('Помогаю детям развивать речь через игру и спокойное общение. Работаю с семьями, подбирая упражнения под возраст и интересы ребёнка.','I help children develop communication through play and a calm, supportive approach. I work with families to adapt activities to each child’s age and interests.','Oyun və sakit ünsiyyət vasitəsilə uşaqlara nitqlərini inkişaf etdirməyə kömək edirəm. Ailələrlə birlikdə uşağın yaşına və maraqlarına uyğun məşqlər seçirəm.');
function profile(){let empty=state==='empty';return `<div class="hero"><p class="eyebrow">${t('Специалисты / Логопедия','Specialists / Speech therapy','Mütəxəssislər / Loqopediya')}</p><div class="identity"><div class="avatar" aria-hidden="true">LM</div><div><h1>${personName}</h1><p>${roleName}</p><div class="pills">${pill(icon('verified')+t('Личность подтверждена','Identity verified','Şəxsiyyət təsdiqlənib'))}${pill(t('Онлайн и очно','Online & in person','Onlayn və əyani'))}</div></div></div><p>${bio}</p><dl class="facts"><div><dt>${t('Возраст детей','Children’s ages','Uşaqların yaşı')}</dt><dd>${t('3–12 лет','3–12 years','3–12 yaş')}</dd></div><div><dt>${t('Языки общения','Session languages','Ünsiyyət dilləri')}</dt><dd>${t('Азербайджанский, русский','Azerbaijani, Russian','Azərbaycan, rus')}</dd></div><div><dt>${t('Формат','Session format','Format')}</dt><dd>${t('По предварительной записи','By appointment','Əvvəlcədən qeydiyyatla')}</dd></div></dl><div class="actions">${button(icon('call')+t('Показать контакт','Show contact','Əlaqəni göstər'),'contact','primary')}<a class="btn secondary" href="#practice">${t('Места практики','Practice locations','Praktika məkanları')}</a></div><p id="contact-result" class="live" role="status"></p></div><div class="split"><div><section class="card" id="practice"><h2>${t('Где проходят занятия','Where sessions take place','Məşğələlər harada keçirilir')}</h2>${empty?notice(t('Место пока не указано','No location listed yet','Məkan hələ göstərilməyib'),t('Доступны онлайн-занятия по договорённости.','Online sessions are available by arrangement.','Razılaşma ilə onlayn məşğələlər mümkündür.')):`<ul class="rows"><li><div class="row-head"><h3>${t('Независимый кабинет','Independent practice','Müstəqil kabinet')}</h3>${pill(t('Текущая практика','Current practice','Cari praktika'))}</div><p>${t('Баку · Ясамаль · демонстрационный адрес','Baku · Yasamal · demonstration address','Bakı · Yasamal · nümunə ünvan')}</p><p class="muted small">${t('По записи · от 40 ₼ за занятие','By appointment · from ₼40 per session','Qeydiyyatla · məşğələ üçün 40 ₼-dan')}</p></li><li><h3>${t('Онлайн-занятия','Online sessions','Onlayn məşğələlər')}</h3><p>${t('Для семей из любого района. Ссылку и время согласуйте со специалистом.','For families from any district. Arrange a time and meeting link with the specialist.','İstənilən rayondan ailələr üçün. Vaxtı və görüş linkini mütəxəssislə razılaşdırın.')}</p></li></ul>`}</section><section class="card"><h2>${t('Сотрудничество','Cooperation','Əməkdaşlıq')}</h2><ul class="rows"><li><div class="row-head"><h3>${t('Центр «Новый шаг»','New Step Center','Yeni Addım Mərkəzi')}</h3>${pill(t('Обе стороны подтвердили','Both parties confirmed','Hər iki tərəf təsdiqləyib'))}</div><p>${roleName} · 01.09.2026 — ${t('по настоящее время','present','indiyədək')}</p></li></ul><details class="history" ${state==='history'?'open':''}><summary>${t('Прошлое сотрудничество','Past cooperation','Keçmiş əməkdaşlıq')}</summary><p>${t('Студия «Рост» · 01.02.2024–30.06.2025','Growth Studio · 01.02.2024–30.06.2025','İnkişaf Studiyası · 01.02.2024–30.06.2025')}</p><p class="muted small">${t('Участие завершено. Это не текущее место работы.','Cooperation has ended. This is not a current workplace.','İştirak başa çatıb. Bu, cari iş yeri deyil.')}</p></details></section></div><aside><section class="card"><h2>${t('Квалификация','Qualifications','Kvalifikasiya')}</h2>${empty||['revoked','pending','rejected'].includes(state)?`<p class="muted">${t('Публичные документы не добавлены.','No public documents shared.','İctimai sənəd paylaşılmayıb.')}</p>`:`<div class="document-row">${icon('workspace_premium')}<div><h3>${t('Сертификат по развитию речи','Speech development certificate','Nitqin inkişafı sertifikatı')}</h3><p class="small">2025</p>${pill(t('Одобрено KidsMap','Approved by KidsMap','KidsMap təsdiqləyib'))}<p class="muted small">${t('Опубликовано по выбору специалиста.','Shared by the specialist’s choice.','Mütəxəssisin seçimi ilə paylaşılıb.')}</p>${button(t('Посмотреть сертификат','View certificate','Sertifikata bax'),'certificate')}</div></div>`}<p id="certificate-result" class="live" role="status"></p></section><section class="card"><h2>${t('О профиле','About this profile','Profil haqqında')}</h2><p class="small muted">${t('Проверка личности подтверждает владение профилем. Она не заменяет оценку услуг специалиста.','Identity verification confirms control of this profile. It does not replace your assessment of a specialist’s services.','Şəxsiyyət yoxlaması profilə sahibliyi təsdiqləyir. Bu, mütəxəssisin xidmətlərini qiymətləndirməyi əvəz etmir.')}</p></section></aside></div>`;}
function person(){if(state==='denied')return denied();return head(names.person,t('Личные сведения меняете только вы. Связи с организациями подтверждаются отдельно.','Only you edit your personal details. Organization cooperation is confirmed separately.','Şəxsi məlumatları yalnız siz dəyişirsiniz. Təşkilatlarla əlaqələr ayrıca təsdiqlənir.'))+commonState()+`<form id="person-form" novalidate><section class="card"><div class="row-head"><h2>${t('О вас','About you','Haqqınızda')}</h2>${pill(t('Подтверждённый профиль','Verified profile','Təsdiqlənmiş profil'))}</div><div class="fields">${field('person-name',t('Имя и фамилия','Full name','Ad və soyad'),personName,'text','',true)}${field('person-phone',t('Публичный контакт','Public contact','İctimai əlaqə'),'','text',t('Будет доступен родителям после раскрытия контакта.','Parents can reveal this contact on your public profile.','Valideynlər ictimai profildə bu əlaqəni aça biləcəklər.'))}</div><div class="field"><label for="person-bio">${t('О себе','Biography','Haqqımda')}</label><textarea id="person-bio">${bio}</textarea></div><div class="fields">${field('person-specialty',t('Специализация','Specialty','İxtisas'),roleName)}${field('person-age',t('Возраст детей','Children’s ages','Uşaqların yaşı'),t('3–12 лет','3–12 years','3–12 yaş'))}</div><label class="check"><input id="profile-published" type="checkbox" checked>${t('Показывать профиль в каталоге','Show my profile in the catalog','Profilimi kataloqda göstər')}</label></section><section class="card"><h2>${t('Ваша практика','Your practice','Sizin praktikanız')}</h2><div class="field"><label for="practice-mode">${t('Формат занятий','Session format','Məşğələ formatı')}</label><select id="practice-mode"><option value="both">${t('Очно и онлайн','In person & online','Əyani və onlayn')}</option><option value="online">${t('Только онлайн','Online only','Yalnız onlayn')}</option><option value="office">${t('Только очно','In person only','Yalnız əyani')}</option></select><p class="help" id="practice-help">${t('Переход на онлайн сохраняет историю прежних мест практики.','Switching to online preserves past practice locations.','Onlayna keçid əvvəlki praktika məkanlarının tarixçəsini saxlayır.')}</p></div><div id="office-fields"><h3>${t('Независимый кабинет','Independent practice','Müstəqil kabinet')}</h3><p class="muted small">${t('Вы управляете этим местом практики сами; оно не передаёт организации доступ к вашему профилю.','You manage this practice yourself; it gives an organization no access to your personal profile.','Bu praktikanı özünüz idarə edirsiniz; təşkilata şəxsi profilinizə giriş vermir.')}</p><div class="fields">${field('practice-district',t('Район','District','Rayon'),t('Ясамаль','Yasamal','Yasamal'))}${field('practice-address',t('Адрес для посетителей','Visitor address','Ziyarətçi ünvanı'),t('Демонстрационный адрес','Demonstration address','Nümunə ünvan'))}</div></div><p id="online-note" class="notice" hidden>${t('Предыдущий кабинет останется в истории. Для онлайн не создаётся вымышленный адрес.','The previous practice stays in history. No invented address is created for online sessions.','Əvvəlki kabinet tarixçədə qalır. Onlayn üçün uydurma ünvan yaradılmır.')}</p><details class="history" open><summary>${t('История мест практики','Practice location history','Praktika məkanlarının tarixçəsi')}</summary><p>${t('Кабинет · Насими · до 30.06.2025','Practice · Nasimi · until 30.06.2025','Kabinet · Nəsimi · 30.06.2025-dək')}</p><p class="muted small">${t('Не показывается как текущее место практики.','Not shown as a current practice location.','Cari praktika məkanı kimi göstərilmir.')}</p></details></section><section class="card"><h2>${t('Приглашение к сотрудничеству','Cooperation invitation','Əməkdaşlıq dəvəti')}</h2><p>${t('Центр «Новый шаг»','New Step Center','Yeni Addım Mərkəzi')} · ${roleName}</p><p class="muted small">01.09.2026 — ${t('без даты окончания','no end date','bitmə tarixi yoxdur')}</p><div class="consents"><div class="consent"><strong>${t('Организация','Organization','Təşkilat')}</strong>${pill(t('Подтверждено','Confirmed','Təsdiqlənib'))}</div><div class="consent"><strong>${t('Ваше согласие','Your consent','Sizin razılığınız')}</strong>${pill(state==='active'?t('Подтверждено','Confirmed','Təsdiqlənib'):t('Ожидается','Awaiting consent','Razılıq gözlənilir'),state==='active'?'':'warn')}</div></div>${state!=='active'?button(t('Подтвердить своё участие','Confirm my participation','İştirakımı təsdiqlə'),'person-consent'):notice(t('Связь подтверждена обеими сторонами','Both parties confirmed this cooperation','Əlaqəni hər iki tərəf təsdiqləyib'),t('Период и роль сохранены в истории.','The period and role are preserved in history.','Müddət və vəzifə tarixçədə saxlanılır.'))}</section><div class="actions"><button type="submit" class="btn primary" data-action="save-person">${t('Сохранить профиль','Save profile','Profili saxla')}</button><a class="btn secondary" href="${url('profile')}">${t('Посмотреть публичный профиль','View public profile','İctimai profilə bax')}</a></div><p id="form-result" class="live" role="status"></p></form>`;}
function organization(){if(state==='denied')return denied();let active=state==='active',past=state==='history'||state==='withdrawn';const orgConfirmed=active||(state==='pending'&&firstConsent==='organization')||(past&&['both','organization'].includes(consentHistory)),personConfirmed=active||(state==='pending'&&firstConsent==='person')||(past&&['both','person'].includes(consentHistory));return head(names.organization,t('Приглашайте человека к сотрудничеству. Его профиль, контакты и документы остаются под его управлением.','Invite a person to cooperate. Their profile, personal contacts and documents remain under their control.','Şəxsi əməkdaşlığa dəvət edin. Profili, şəxsi əlaqələri və sənədləri öz idarəsində qalır.'))+commonState()+`<section class="card"><p class="eyebrow">${t('Центр «Новый шаг»','New Step Center','Yeni Addım Mərkəzi')}</p><h2>${t('Предложить сотрудничество','Propose cooperation','Əməkdaşlıq təklif et')}</h2><form id="invitation-form" novalidate><div class="fields">${field('specialist-id',t('Ссылка или ID профиля','Profile link or ID','Profil linki və ya ID'),'SP-1042','text',t('Совпадение имени не подтверждает личность.','A matching name does not verify identity.','Adın uyğunluğu şəxsiyyəti təsdiqləmir.'),true)}${field('employment-role',t('Роль в организации','Role in organization','Təşkilatda vəzifə'),roleName,'text','',true)}${field('employment-start',t('Начало сотрудничества','Cooperation starts','Əməkdaşlığın başlanğıcı'),'2026-09-01','date','',true)}${field('employment-end',t('Окончание (необязательно)','End date (optional)','Bitmə tarixi (məcburi deyil)'),'','date')}</div><button type="submit" class="btn primary" data-action="invite">${t('Создать предложение','Create proposal','Təklif yarat')}</button><p id="invite-result" class="live" role="status"></p></form></section><section class="card" id="cooperation-card"><h2>${t('Связь с профилем','Profile cooperation','Profil ilə əlaqə')}</h2>${state==='empty'?`<p class="muted">${t('Пока нет предложений сотрудничества.','No cooperation proposals yet.','Hələ əməkdaşlıq təklifi yoxdur.')}</p>`:`<div class="row-head"><h3>${personName}</h3>${pill(past?t('Завершено / отменено','Ended / cancelled','Bitib / ləğv edilib'):active?t('Активное сотрудничество','Active cooperation','Aktiv əməkdaşlıq'):t('Не подтверждено обеими сторонами','Not yet confirmed by both parties','Hər iki tərəf hələ təsdiqləməyib'),past?'dim':active?'':'warn')}</div><p>${roleName} · 01.09.2026 — ${t('без даты окончания','no end date','bitmə tarixi yoxdur')}</p>${past?notice(t('Участие осталось в истории','Participation stays in history','İştirak tarixçədə qalır'),t('Эта запись не отображается как текущая работа.','This record is not displayed as a current job.','Bu qeyd cari iş kimi göstərilmir.')):`<div class="consents"><div class="consent"><strong>${t('Согласие организации','Organization consent','Təşkilatın razılığı')}</strong>${pill(!orgConfirmed?t('Ожидается','Awaiting consent','Razılıq gözlənilir'):t('Подтверждено','Confirmed','Təsdiqlənib'),!orgConfirmed?'warn':'')}</div><div class="consent"><strong>${t('Согласие специалиста','Specialist consent','Mütəxəssisin razılığı')}</strong>${pill(personConfirmed?t('Подтверждено','Confirmed','Təsdiqlənib'):t('Ожидается','Awaiting consent','Razılıq gözlənilir'),personConfirmed?'':'warn')}</div></div><p class="small muted">${t('Приглашение и доступ к филиалу не заменяют согласие человека.','An invitation or branch access does not replace the person’s consent.','Dəvət və ya filiala giriş şəxsin razılığını əvəz etmir.')}</p><div class="actions">${actor==='person'&&!personConfirmed?button(t('Подтвердить как специалист','Confirm as the specialist','Mütəxəssis kimi təsdiqlə'),'person-consent','primary'):actor==='organization'&&!orgConfirmed?button(t('Подтвердить от организации','Confirm for organization','Təşkilat adından təsdiqlə'),'org-consent','primary'):''}${button(t('Отменить участие','Cancel cooperation','Əməkdaşlığı ləğv et'),'cancel-employment','danger')}</div>`}<details class="history" open><summary>${t('История решений','Decision history','Qərarların tarixçəsi')}</summary><ul><li>${t('Предложение создано · роль и период зафиксированы','Proposal created · role and period recorded','Təklif yaradıldı · vəzifə və müddət qeydə alındı')}</li>${orgConfirmed?`<li>${t('Организация подтвердила участие','Organization confirmed cooperation','Təşkilat əməkdaşlığı təsdiqlədi')}</li>`:''}${personConfirmed?`<li>${t('Специалист отдельно подтвердил участие','Specialist separately confirmed cooperation','Mütəxəssis əməkdaşlığı ayrıca təsdiqlədi')}</li>`:''}${past?`<li>${t('Участие отменено 03.10.2026 · прежние записи сохранены','Cooperation cancelled 03.10.2026 · previous records preserved','Əməkdaşlıq 03.10.2026-da ləğv edildi · əvvəlki qeydlər saxlanıldı')}</li>`:''}</ul></details>`}</section>${notice(t('Личные сведения — у специалиста','Personal details belong to the specialist','Şəxsi məlumatları mütəxəssis idarə edir'),t('Организация не получает редактирование биографии, личных контактов или документов.','The organization cannot edit biography, personal contacts or documents.','Təşkilat bioqrafiyanı, şəxsi əlaqələri və sənədləri dəyişə bilməz.'))}`;}
function claim(){if(state==='denied')return denied();let done=['pending','rejected','approved','withdrawn'].includes(state);return head(names.claim,t('Один профиль человека. KidsMap проверяет заявку; автор и предлагающая организация не получают владение автоматически.','One profile per person. KidsMap reviews the claim; authors and proposing organizations do not automatically own it.','Bir şəxs üçün bir profil. KidsMap müraciəti yoxlayır; müəllif və təklif edən təşkilat avtomatik sahiblik almır.'))+commonState()+`<section class="card"><div class="identity"><div class="avatar" aria-hidden="true">LM</div><div><h2>${personName}</h2><p>${roleName}</p><p class="muted small">SP-1042 · /specialists/leyla-mammadova/</p></div></div>${done?notice(stateNames[state],state==='approved'?t('KidsMap подтвердил принадлежность профиля вашему аккаунту. Это решение не подтверждает автоматически связи с организациями.','KidsMap verified that this profile belongs to your account. Organization cooperation is not automatically confirmed.','KidsMap bu profilin hesabınıza aid olduğunu təsdiqlədi. Təşkilatlarla əlaqələr avtomatik təsdiqlənmir.'):state==='rejected'?t('Не удалось подтвердить принадлежность профиля. Уточните сведения перед новой заявкой.','Profile ownership could not be verified. Clarify the details before submitting a new claim.','Profilə sahiblik təsdiqlənmədi. Yeni müraciətdən əvvəl məlumatları dəqiqləşdirin.'):state==='withdrawn'?t('Профиль и его прежний URL сохранены.','The profile and its old URL are preserved.','Profil və köhnə URL saxlanılıb.'):t('До решения KidsMap редактирование личных сведений недоступно.','Personal details cannot be edited until KidsMap makes a decision.','KidsMap qərar verənədək şəxsi məlumatlar dəyişdirilə bilməz.'),state==='rejected'?'bad':state==='pending'?'warn':''):`<form id="claim-form" novalidate><label class="check"><input id="claim-person" type="checkbox" required>${t('Это мой личный профиль. Я подаю заявку от своего имени.','This is my personal profile. I am claiming it for myself.','Bu mənim şəxsi profilimdir. Öz adımdan müraciət edirəm.')}</label><p class="small muted">${t('Совпадение имени или место работы не являются подтверждением личности.','A name match or workplace does not prove identity.','Adın uyğunluğu və ya iş yeri şəxsiyyəti sübut etmir.')}</p><div class="actions"><button type="submit" class="btn primary" data-action="submit-claim">${t('Отправить заявку KidsMap','Submit claim to KidsMap','KidsMap-a müraciət göndər')}</button></div><p id="claim-result" class="live" role="status"></p></form>`}<div class="actions">${state==='pending'?button(t('Отозвать заявку','Withdraw claim','Müraciəti geri götür'),'withdraw-claim','danger'):state==='approved'?`<a class="btn primary" href="${url('person')}">${t('Открыть мой профиль','Open my profile','Profilimi aç')}</a>`:state==='rejected'||state==='withdrawn'?button(t('Подготовить новую заявку','Prepare a new claim','Yeni müraciət hazırla'),'reload'):''}</div></section>${notice(t('Приватная проверка','Private review','Məxfi yoxlama'),t('Доказательства личности не публикуются в профиле и не становятся сертификатами.','Identity evidence is not published on the profile and never becomes a qualification certificate.','Şəxsiyyət sübutları profildə paylaşılmır və kvalifikasiya sertifikatına çevrilmir.'))}`;}
function documents(){if(state==='denied')return denied();let approved=['approved','revoked'].includes(state),opted=state==='approved';return head(names.documents,t('Проверка KidsMap и ваш публичный выбор — два разных действия. Личность и доказательства владения всегда приватны.','KidsMap review and your choice to share are two different actions. Identity and ownership evidence always stay private.','KidsMap yoxlaması və ictimai paylaşım seçiminiz iki ayrı əməliyyatdır. Şəxsiyyət və sahiblik sübutları həmişə məxfidir.'))+commonState()+`<section class="card"><h2>${t('Добавить документ','Add a document','Sənəd əlavə et')}</h2><form id="document-form" novalidate><div class="fields"><div class="field"><label for="document-type">${t('Назначение','Document purpose','Sənədin təyinatı')}</label><select id="document-type"><option value="certificate">${t('Сертификат','Certificate','Sertifikat')}</option><option value="diploma">${t('Диплом','Diploma','Diplom')}</option><option value="identity">${t('Подтверждение личности (всегда приватно)','Identity evidence (always private)','Şəxsiyyət sübutu (həmişə məxfi)')}</option></select></div>${field('document-name',t('Название','Title','Başlıq'),'','text','',true)}</div><div class="field"><label for="document-file">${t('Файл','File','Fayl')}</label><input id="document-file" type="file" accept=".pdf,.png,.jpg,.jpeg" aria-describedby="file-help" required><p class="help" id="file-help">${t('PDF, PNG, JPG · до 10 MiB. В макете файл никуда не отправляется.','PDF, PNG, JPG · up to 10 MiB. No file is uploaded in this prototype.','PDF, PNG, JPG · 10 MiB-dək. Maketdə fayl heç yerə göndərilmir.')}</p></div><div id="upload-choice"><label class="check"><input id="upload-optin" type="checkbox">${t('Хочу показывать квалификацию после одобрения KidsMap','I want to share this qualification after KidsMap approval','KidsMap təsdiqindən sonra bu kvalifikasiyanı paylaşmaq istəyirəm')}</label></div><p id="identity-note" class="notice" hidden>${t('Подтверждение личности всегда приватно. Публичного переключателя для него нет.','Identity evidence always stays private. It has no public switch.','Şəxsiyyət sübutu həmişə məxfidir. Onun üçün ictimai seçim yoxdur.')}</p><button type="submit" class="btn primary" data-action="upload-document">${t('Добавить на проверку','Add for review','Yoxlamaya əlavə et')}</button><p id="document-result" class="live" role="status"></p></form></section><section class="card"><h2>${t('Документы профиля','Profile documents','Profilin sənədləri')}</h2>${state==='empty'?`<p class="muted">${t('Вы ещё не добавили документы.','You have not added any documents yet.','Hələ sənəd əlavə etməmisiniz.')}</p>`:`<ul class="rows"><li class="document-row">${icon('lock')}<div><h3>${t('Подтверждение личности','Identity evidence','Şəxsiyyət sübutu')}</h3><div class="pills">${pill(t('Всегда приватно','Always private','Həmişə məxfi'),'dim')}${pill(t('Одобрено KidsMap','Approved by KidsMap','KidsMap təsdiqləyib'))}</div><p class="small muted">${t('Видно вам и назначенному проверяющему. Не публикуется при любых настройках.','Visible to you and a dedicated reviewer. Never published under any setting.','Sizə və xüsusi səlahiyyətli yoxlayıcıya görünür. Heç bir ayarla paylaşılmır.')}</p>${button(t('Открыть приватный документ','Open private document','Məxfi sənədi aç'),'private-document')}</div></li><li class="document-row">${icon('workspace_premium')}<div><h3>${t('Сертификат по развитию речи','Speech development certificate','Nitqin inkişafı sertifikatı')}</h3><div class="pills">${pill(approved?t('Одобрено KidsMap','Approved by KidsMap','KidsMap təsdiqləyib'):state==='rejected'?t('Отклонено KidsMap','Rejected by KidsMap','KidsMap rədd edib'):t('На проверке','Under review','Yoxlanılır'),approved?'':state==='rejected'?'bad':'warn')}<span id="certificate-visibility" class="pill ${opted?'':'dim'}">${opted?t('Публичный','Public','İctimai'):t('Приватный','Private','Məxfi')}</span></div><label class="check"><input id="certificate-optin" type="checkbox" ${opted?'checked':''}>${t('Показывать в публичном профиле','Show on my public profile','İctimai profilimdə göstər')}</label><p class="small muted" id="visibility-explanation">${approved?opted?t('Есть ваше согласие и одобрение KidsMap.','Your consent and KidsMap approval are both present.','Sizin razılığınız və KidsMap təsdiqi var.'):t('Одобрен, но скрыт по вашему выбору.','Approved, but hidden by your choice.','Təsdiqlənib, amma sizin seçiminizlə gizlidir.'):t('Даже при вашем выборе остаётся приватным до одобрения KidsMap.','Even with your choice to share, it stays private until KidsMap approves it.','Paylaşma seçiminiz olsa belə, KidsMap təsdiqinədək məxfi qalır.')}</p>${state==='rejected'?notice(t('Причина отклонения','Rejection reason','Rədd səbəbi'),t('В демонстрационном файле не читается название квалификации. Добавьте новый документ.','The qualification title is unreadable in this demonstration file. Add a new document.','Nümunə faylda kvalifikasiyanın adı oxunmur. Yeni sənəd əlavə edin.'),'bad'):''}<p id="optin-result" class="live" role="status"></p></div></li></ul>`}</section>${notice(t('Старый файл не меняет назначение','An existing file cannot change purpose','Mövcud faylın təyinatı dəyişmir'),t('Для другого документа добавьте новый файл. Отмена публичного выбора скрывает квалификацию, сохраняя приватную запись.','Add a new file for a different document. Withdrawing your public choice hides the qualification while preserving its private record.','Başqa sənəd üçün yeni fayl əlavə edin. İctimai seçimin ləğvi kvalifikasiyanı gizlədir, məxfi qeyd saxlanılır.'))}`;}
function review(){if(state==='denied')return denied();return head(names.review,t('Доступ назначенному проверяющему. Решение о личности отдельно от квалификации и публичного выбора человека.','Dedicated reviewer access. Identity decisions are separate from qualifications and the person’s public choice.','Xüsusi yoxlayıcı üçün giriş. Şəxsiyyət qərarı kvalifikasiyadan və şəxsin ictimai seçimindən ayrıdır.'))+commonState()+notice(t('Служебный доступ к приватным сведениям','Dedicated access to private information','Məxfi məlumatlara xüsusi giriş'),t('Обычный сотрудник, волонтёр и управляющий организацией не получают этот доступ.','Ordinary staff, volunteers and organization managers do not have this access.','Adi əməkdaşlar, könüllülər və təşkilat idarəçiləri bu girişi əldə etmir.'))+`<section class="card"><h2>${t('Заявка на личный профиль','Personal profile claim','Şəxsi profil müraciəti')}</h2><p>${personName} · SP-1042</p><p class="small muted">${t('Заявитель · демонстрационный аккаунт A-501','Applicant · demonstration account A-501','Müraciət edən · nümunə hesab A-501')}</p>${state==='approved'||state==='rejected'?notice(stateNames[state],t('Решение записано только в состоянии макета. Связи с организациями не изменены.','Decision recorded only in this prototype state. Organization cooperation remains unchanged.','Qərar yalnız maketin vəziyyətində qeydə alındı. Təşkilat əlaqələri dəyişməyib.')):`<div class="field"><label for="claim-review-reason">${t('Основание решения','Decision reason','Qərarın əsası')}</label><textarea id="claim-review-reason" aria-describedby="claim-review-help"></textarea><p id="claim-review-help" class="help">${t('При отклонении объясните, что требуется уточнить.','If rejecting, explain which details need clarification.','Rədd edərkən hansı məlumatların dəqiqləşdirilməli olduğunu izah edin.')}</p></div><div class="actions">${button(t('Подтвердить принадлежность профиля','Approve profile ownership','Profil sahibliyini təsdiqlə'),'approve-claim','primary')}${button(t('Отклонить заявку','Reject claim','Müraciəti rədd et'),'reject-claim','danger')}</div><p id="review-result" class="live" role="status"></p>`}</section><section class="card"><h2>${t('Проверка квалификации','Qualification review','Kvalifikasiyanın yoxlanması')}</h2><div class="document-row">${icon('description')}<div><h3>${t('Сертификат по развитию речи','Speech development certificate','Nitqin inkişafı sertifikatı')}</h3><p class="small muted">${t('Тип: сертификат · приватный файл','Type: certificate · private file','Növ: sertifikat · məxfi fayl')}</p>${button(t('Открыть приватный файл','Open private file','Məxfi faylı aç'),'private-document')}</div></div><div class="consents"><div class="consent"><strong>${t('Проверка KidsMap','KidsMap decision','KidsMap qərarı')}</strong><span id="document-review-status">${t('Ожидается','Pending','Gözlənilir')}</span></div><div class="consent"><strong>${t('Публичный выбор специалиста','Specialist’s public choice','Mütəxəssisin ictimai seçimi')}</strong>${t('Не выбран · проверяющий не меняет','Not selected · reviewer cannot change','Seçilməyib · yoxlayıcı dəyişə bilməz')}</div></div><div class="field"><label for="document-review-reason">${t('Комментарий к документу','Document comment','Sənədə şərh')}</label><textarea id="document-review-reason"></textarea></div><div class="actions">${button(t('Одобрить документ','Approve document','Sənədi təsdiqlə'),'approve-document','primary')}${button(t('Отклонить документ','Reject document','Sənədi rədd et'),'reject-document','danger')}</div><p id="document-review-result" class="live" role="status"></p></section>`;}
function reconciliation(){return head(names.reconciliation,t('Демонстрационная сверка существующих записей. Ни имя, ни прежний владелец, ни место практики не подтверждают личность или обе стороны сотрудничества.','Demonstration reconciliation of existing records. Names, previous owners and practice locations prove neither identity nor both parties’ cooperation consent.','Mövcud qeydlərin nümayiş tutuşdurulması. Ad, əvvəlki sahib və praktika məkanı nə şəxsiyyəti, nə də hər iki tərəfin razılığını təsdiqləyir.'))+commonState()+`<div class="mini-grid"><div><strong>3</strong><span>${t('Профиля сохранено','Profiles preserved','Profil saxlanıldı')}</span></div><div><strong>3</strong><span>${t('Старых URL сохранено','Old URLs preserved','Köhnə URL saxlanıldı')}</span></div><div><strong>2</strong><span>${t('Ручные проверки','Manual reviews','Əl ilə yoxlama')}</span></div></div><section class="card"><h2>${t('Результат по идентификаторам','Results by identifier','İdentifikator üzrə nəticələr')}</h2><div class="record"><div class="row-head"><h3>SP-1042 · ${personName}</h3>${pill(t('ID и URL сохранены','ID & URL preserved','ID və URL saxlanılıb'))}</div><p><code>/specialists/leyla-mammadova/</code></p><p class="muted small">${t('Онлайн и независимый кабинет сохранены. Личность подтверждается отдельным claim.','Online and independent practice preserved. Identity requires a separate claim.','Onlayn və müstəqil kabinet saxlanılıb. Şəxsiyyət ayrıca müraciətlə təsdiqlənir.')}</p></div><div class="record"><div class="row-head"><h3>SP-1043</h3>${pill(t('Ручная проверка','Manual review','Əl ilə yoxlama'),'warn')}</div><p>${t('Совпадение имени у двух записей. Не объединены.','Two records have matching names. They were not merged.','İki qeydin adı uyğundur. Birləşdirilməyib.')}</p><p class="muted small">${t('Старый URL и ID профиля сохранены; владение не назначено.','Old URL and profile ID preserved; ownership not assigned.','Köhnə URL və profil ID saxlanılıb; sahiblik təyin edilməyib.')}</p></div><div class="record"><div class="row-head"><h3>EMP-207 · ORG-301</h3>${pill(t('Подтверждения отсутствуют','Confirmations missing','Təsdiqlər yoxdur'),'warn')}</div><p>${t('Историческая связь с местом не стала подтверждённым сотрудничеством.','A historical place link did not become confirmed cooperation.','Tarixi məkan əlaqəsi təsdiqlənmiş əməkdaşlığa çevrilməyib.')}</p><p class="muted small">${t('Роль и период уточняются. Обе стороны подтверждают отдельно.','Role and period require clarification. Each party confirms separately.','Vəzifə və müddət dəqiqləşdirilir. Hər tərəf ayrıca təsdiqləyir.')}</p></div><div class="actions">${button(t('Проверить демонстрационную сверку','Check demonstration reconciliation','Nümunə tutuşdurmanı yoxla'),'reconcile','primary')}</div><p id="reconciliation-result" class="live" role="status"></p></section>${notice(t('Это макет сверки, не перенос данных','This is a reconciliation design, not a data transfer','Bu tutuşdurma maketidir, məlumat köçürməsi deyil'),t('Проверка fixtures, nested ID, ролей и старых URL выполняется после принятия новых экранов. Здесь нет подключения к БД.','Fixture transfer, nested ID, role and old URL tests follow screen acceptance. This prototype has no database connection.','Fixture köçürməsi, daxili ID, rol və köhnə URL testləri ekranlar qəbul ediləndən sonra aparılır. Bu maketin verilənlər bazası bağlantısı yoxdur.'))}`;}
const renderers={index,profile,person,organization,claim,documents,review,reconciliation};
function render(){document.documentElement.lang=lang;document.title=`KidsMap · ${names[screen]}`;document.body.dataset.state=state;document.getElementById('app').innerHTML=`<a class="skip" href="#main">${t('К содержимому','Skip to content','Məzmunu keç')}</a><header class="header"><div class="header-inner"><a class="brand" href="${url('index')}"><img src="../../../../static/img/logo-mark.svg" alt="" width="36" height="42">KidsMap</a><div class="header-end"><nav class="locale" aria-label="${t('Язык','Language','Dil')}">${['az','ru','en'].map(l=>`<a href="${esc(languageUrl(l))}" lang="${l}" ${l===lang?'aria-current="page"':''}>${l.toUpperCase()}</a>`).join('')}</nav></div></div></header><div class="prototype-bar">${t('Дизайн на рассмотрении · вымышленные данные · без записи в приложение','Design awaiting acceptance · synthetic data · no application writes','Dizayn qəbul gözləyir · uydurma məlumatlar · tətbiqə yazılmır')}</div><div class="shell"><div class="layout"><nav class="navigation" aria-label="${t('Экраны специалистов','Specialist screens','Mütəxəssis ekranları')}">${Object.keys(names).map(k=>`<a href="${url(k)}" ${k===screen?'aria-current="page"':''}>${icon(icons[k])}${names[k]}</a>`).join('')}<small>specialist-25-r1<br>${t('Локальный макет','Local prototype','Lokal maket')}</small></nav><main id="main" class="content" tabindex="-1">${renderers[screen]()}<section class="demo-tools" aria-label="${t('Настройки демонстрации','Demonstration controls','Nümayiş seçimləri')}"><label for="demo-state">${t('Состояние макета','Prototype state','Maket vəziyyəti')}</label><select id="demo-state">${states.map(s=>`<option value="${s}" ${s===state?'selected':''}>${stateNames[s]}</option>`).join('')}</select>${screen==='organization'?`<label for="demo-actor">${t('Роль в демонстрации (не переключение прав)','Demonstration role (does not switch real permissions)','Nümayiş rolu (real səlahiyyəti dəyişmir)')}</label><select id="demo-actor"><option value="organization" ${actor==='organization'?'selected':''}>${t('Организация','Organization','Təşkilat')}</option><option value="person" ${actor==='person'?'selected':''}>${t('Подтверждённый специалист','Verified specialist','Təsdiqlənmiş mütəxəssis')}</option></select>`:''}<p>${t('Сценарии доступны для просмотра. Права, версии и статусы при реализации определяет сервер.','Scenarios are available for review. The server determines permissions, versions and statuses in implementation.','Ssenarilər baxış üçün açıqdır. Tətbiqdə səlahiyyətləri, versiyaları və statusları server müəyyən edir.')}</p></section></main></div></div><footer class="footer">KidsMap · specialist-25-r1 · ${t('Макеты не приняты','Designs not yet accepted','Maketlər hələ qəbul edilməyib')}</footer>`;bind();}
function setState(next){state=next;params.set('state',next);params.set('lang',lang);history.replaceState(null,'',`${location.pathname}?${params}`);render();document.getElementById('main').focus();}
function say(id,message,error=false){const el=document.getElementById(id);el.textContent=message;el.classList.toggle('error',error);if(error)el.setAttribute('role','alert');else el.setAttribute('role','status');}
function invalid(input,id,message){input.setAttribute('aria-invalid','true');input.setAttribute('aria-describedby',id);say(id,message,true);input.focus();}
function bind(){document.getElementById('demo-state').addEventListener('change',e=>setState(e.target.value));document.getElementById('demo-actor')?.addEventListener('change',e=>{actor=e.target.value;params.set('actor',actor);history.replaceState(null,'',`${location.pathname}?${params}`);render();});
 document.querySelectorAll('[data-action]').forEach(el=>el.addEventListener('click',()=>{const a=el.dataset.action;
 if(a==='reload')setState('default');if(a==='org-consent'&&actor==='organization'){if(state==='pending'&&firstConsent==='person')setState('active');else{firstConsent='organization';params.set('consent','organization');setState('pending');}}if(a==='person-consent'){if(screen==='person'||(screen==='organization'&&state==='pending'&&firstConsent==='organization'))setState('active');else if(screen==='organization'&&actor==='person'){firstConsent='person';params.set('consent','person');setState('pending');}}if(a==='cancel-employment'){consentHistory=state==='active'?'both':state==='pending'?firstConsent:'none';params.set('consentHistory',consentHistory);setState('history');}if(a==='withdraw-claim')setState('withdrawn');if(a==='approve-claim')setState('approved');
 if(a==='contact')say('contact-result',t('Демонстрация: контакт раскрыт. Никакого звонка не выполнено.','Demonstration: contact revealed. No call has been placed.','Nümayiş: əlaqə açıldı. Zəng edilməyib.'));
 if(a==='certificate')say('certificate-result',t('Демонстрация публичного сертификата. Реального файла нет.','Public certificate demonstration. There is no real file.','İctimai sertifikat nümayişi. Real fayl yoxdur.'));
 if(a==='private-document'){const p=document.createElement('p');p.className='live';p.setAttribute('role','status');p.textContent=t('Демонстрация приватного просмотра. Документ не скачивается.','Private viewing demonstration. No document is downloaded.','Məxfi baxış nümayişi. Sənəd endirilmir.');el.parentNode.querySelector('.live')?.remove();el.after(p);}
 if(a==='reject-claim'){let reason=document.getElementById('claim-review-reason');if(!reason.value.trim())invalid(reason,'review-result',t('Укажите причину отклонения.','Provide a rejection reason.','Rədd səbəbini yazın.'));else setState('rejected');}
 if(a==='approve-document'){document.getElementById('document-review-status').textContent=t('Одобрено','Approved','Təsdiqlənib');say('document-review-result',t('Одобрен. Остаётся приватным: специалист не выбрал публикацию.','Approved. Still private: the specialist has not chosen to publish.','Təsdiqlənib. Məxfidir: mütəxəssis paylaşımı seçməyib.'));}
 if(a==='reject-document'){let reason=document.getElementById('document-review-reason');if(!reason.value.trim())invalid(reason,'document-review-result',t('Укажите причину отклонения.','Provide a rejection reason.','Rədd səbəbini yazın.'));else{document.getElementById('document-review-status').textContent=t('Отклонено','Rejected','Rədd edilib');say('document-review-result',t('Документ отклонён и остаётся приватным.','Document rejected and remains private.','Sənəd rədd edilib və məxfi qalır.'));}}
 if(a==='reconcile')say('reconciliation-result',t('Демонстрация: 3 ID и URL сохранены; 2 ручные проверки; 0 автоматических подтверждений. БД не использовалась.','Demonstration: 3 IDs and URLs preserved; 2 manual reviews; 0 automatic confirmations. No database was used.','Nümayiş: 3 ID və URL saxlanıldı; 2 əl ilə yoxlama; 0 avtomatik təsdiq. Verilənlər bazası istifadə edilmədi.'));
 }));
 document.getElementById('person-form')?.addEventListener('submit',e=>{e.preventDefault();let name=document.getElementById('person-name');if(!name.value.trim())invalid(name,'form-result',t('Введите имя и фамилию.','Enter your full name.','Ad və soyadınızı yazın.'));else{say('form-result',t('Профиль сохранён только в состоянии макета.','Profile saved only in this prototype state.','Profil yalnız maketin vəziyyətində saxlanıldı.'));name.removeAttribute('aria-invalid');}});
 document.getElementById('practice-mode')?.addEventListener('change',e=>{let online=e.target.value==='online';document.getElementById('office-fields').hidden=online;document.getElementById('online-note').hidden=!online;});
 document.getElementById('invitation-form')?.addEventListener('submit',e=>{e.preventDefault();let id=document.getElementById('specialist-id'),role=document.getElementById('employment-role'),start=document.getElementById('employment-start'),end=document.getElementById('employment-end');if(!id.value.trim())invalid(id,'invite-result',t('Укажите ID или ссылку профиля.','Enter a profile ID or link.','Profil ID və ya linkini yazın.'));else if(!role.value.trim())invalid(role,'invite-result',t('Укажите роль.','Enter a role.','Vəzifəni yazın.'));else if(!start.value)invalid(start,'invite-result',t('Укажите дату начала.','Enter a start date.','Başlanğıc tarixini yazın.'));else if(end.value&&end.value<start.value)invalid(end,'invite-result',t('Окончание не может быть раньше начала.','End date cannot precede the start date.','Bitmə tarixi başlanğıcdan əvvəl ola bilməz.'));else{setState('default');say('invite-result',t('Предложение создано в макете. Оба согласия ещё ожидаются.','Proposal created in prototype. Both consents are still pending.','Təklif maketdə yaradıldı. Hər iki razılıq hələ gözlənilir.'));}});
 document.getElementById('claim-form')?.addEventListener('submit',e=>{e.preventDefault();let box=document.getElementById('claim-person');if(!box.checked)invalid(box,'claim-result',t('Подтвердите, что подаёте заявку на свой профиль.','Confirm you are claiming your own profile.','Öz profiliniz üçün müraciət etdiyinizi təsdiqləyin.'));else setState('pending');});
 document.getElementById('document-type')?.addEventListener('change',e=>{let identity=e.target.value==='identity';document.getElementById('upload-choice').hidden=identity;document.getElementById('identity-note').hidden=!identity;if(identity)document.getElementById('upload-optin').checked=false;});
 document.getElementById('document-form')?.addEventListener('submit',e=>{e.preventDefault();let name=document.getElementById('document-name'),file=document.getElementById('document-file');if(!name.value.trim())invalid(name,'document-result',t('Введите название документа.','Enter a document title.','Sənəd başlığını yazın.'));else if(!file.files.length)invalid(file,'document-result',t('Выберите демонстрационный файл.','Select a demonstration file.','Nümunə fayl seçin.'));else if(file.files[0].size>10*1024*1024||!/^.+\.(pdf|png|jpe?g)$/i.test(file.files[0].name))invalid(file,'document-result',t('Нужен PDF, PNG или JPG до 10 MiB.','Use PDF, PNG or JPG up to 10 MiB.','10 MiB-dək PDF, PNG və ya JPG seçin.'));else say('document-result',t('Демонстрация: ожидает проверки и остаётся приватным. Файл не отправлен.','Demonstration: awaiting review and still private. No file was uploaded.','Nümayiş: yoxlama gözləyir və məxfidir. Fayl göndərilməyib.'));});
 document.getElementById('certificate-optin')?.addEventListener('change',e=>{const approved=['approved','revoked'].includes(state);const publicNow=approved&&e.target.checked;document.getElementById('certificate-visibility').textContent=publicNow?t('Публичный','Public','İctimai'):t('Приватный','Private','Məxfi');document.getElementById('certificate-visibility').classList.toggle('dim',!publicNow);document.getElementById('visibility-explanation').textContent=publicNow?t('Есть ваше согласие и одобрение KidsMap.','Your consent and KidsMap approval are both present.','Sizin razılığınız və KidsMap təsdiqi var.'):t('Документ остаётся приватным.','The document remains private.','Sənəd məxfi qalır.');say('optin-result',!e.target.checked?t('Публичный выбор отменён. Приватная запись сохранена.','Public choice withdrawn. Private record preserved.','İctimai seçim ləğv edildi. Məxfi qeyd saxlanıldı.'):approved?t('Ваш выбор включён. Одобренная квалификация будет публичной при публикации профиля.','Your choice is enabled. The approved qualification is public when the profile is published.','Seçiminiz aktivdir. Profil yayımlandıqda təsdiqlənmiş kvalifikasiya ictimai olacaq.'):t('Выбор сохранён в макете. До одобрения документ остаётся приватным.','Choice saved in prototype. Document stays private until approval.','Seçim maketdə saxlanıldı. Təsdiqədək sənəd məxfi qalır.'));});
}
render();
